use std::ops::Deref;

struct MyBox<T>(T);

impl<T> MyBox<T> {
    fn new(x: T) -> MyBox<T> {
        MyBox(x)
    }
}

impl<T> Deref for MyBox<T> {
    type Target = T;

    fn deref(&self) -> &T {
        &self.0
    }
}

fn hello(name: &str) {
    println!("Hello, {name}!");
}

fn main() {
    let y = MyBox::new(5);
    println!("{}", *y);   // Rust runs *(y.deref()) behind the scenes

    let name = MyBox::new(String::from("Rust"));
    hello(&name);         // &MyBox<String> becomes &String, then &str
}

// Output:
// 5
// Hello, Rust!

struct Noisy {
    name: String,
}

impl Noisy {
    fn new(name: &str) -> Noisy {
        Noisy { name: String::from(name) }
    }
}

impl Drop for Noisy {
    fn drop(&mut self) {
        println!("dropping {}", self.name);
    }
}

fn main() {
    let first = Noisy::new("first");
    let second = Noisy::new("second");
    println!("made {} and {}", first.name, second.name);
    {
        let temp = Noisy::new("temp");
        println!("inside block with {}", temp.name);
    }
    let early = Noisy::new("early");
    drop(early);   // std's drop function: cleans up right now
    println!("end of main");
}

// Output:
// made first and second
// inside block with temp
// dropping temp
// dropping early
// end of main
// dropping second
// dropping first

