exercise.solution:
struct Guard {
    name: String,
}

impl Drop for Guard {
    fn drop(&mut self) {
        println!("dropping {}", self.name);
    }
}

fn work(first: Guard, second: Guard) {
    println!("guards: {} and {}", first.name, second.name);
    drop(first);
    println!("working");
}

fn main() {
    let first = Guard { name: String::from("first") };
    let second = Guard { name: String::from("second") };
    work(first, second);
}
